def zaslavsky_bound(w, n):
    from math import comb
    return sum(comb(w, k) for k in range(n + 1))

def network_region_bound(input_dim, widths):
    bound = 1
    for w in widths:
        bound *= zaslavsky_bound(w, input_dim)
    return bound

def enumerate_faces(sigma):
    support = [i for i, s in enumerate(sigma) if s != 0]
    from itertools import product
    faces = []
    for bits in product([False, True], repeat=len(support)):
        face = list(sigma)
        for j, idx in enumerate(support):
            if not bits[j]: face[idx] = 0
        faces.append(tuple(face))
    return faces

def gsp_euler(m):
    from math import comb
    return sum((-1)**k * comb(m, k) * 2**k for k in range(m + 1))
